    assert (NP6 : sp1 + 16 + 8 <= p \/ p + 1 <= sp1 + 16).
    { eapply (nc_apart _ _ _ (arl_stklo R) _ p); [exact NCp| apply client_range_stack; clear - SLO LOS SP1 NEEDR NER; lia| intros b' Hb; exact Hb| clear; lia| clear; lia]. }
