  Lemma keep_block_fresh : ltac2:(CDefT.buildp (gd_tbl_A_ecp_mod_p448 ()) "Phq,(1?.$20.VR,VHIA,)Pmq,P,(4.&40.)(5.(4.&8.))P,(2>.$20.VR,VHIA,R2.VLB,VLF,R1.)P,(15.$52.(53.VdX,)$54.)P,(49.(18.$3.$3.)(19.$3.$3.(55.VdX,)(10.+4.(56.VdX,)))VLB,)(38.VR,(57.VLB,VdX,)VLF,(55.VdX,)(10.+4.(56.VdX,)))")
